def equation(eps, T, params):
    a,b,f,g,c,d,k,h,m=params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8]
    u=T-2
    return -(a*np.tanh(b*eps*np.exp(f*u))*np.exp(g*u) + c*u**k*eps**d*np.exp(h*u) + m*eps*np.exp(params[9]*u))
